create policy hp_staff_documents_subject_scope on public.hp_staff_documents as restrictive for all to authenticated using (exists(select 1 from public.hp_personnel_accounts pa where pa.user_id=(select auth.uid()) and pa.personnel_id=hp_staff_documents.personnel_id) or exists(select 1 from public.hp_user_facilities pf where pf.user_id=(select auth.uid()) and (pf.role='ADMIN' or (pf.role='STAFF' and pf.facility_code=hp_staff_documents.facility_code)))) with check (exists(select 1 from public.hp_personnel_accounts pa where pa.user_id=(select auth.uid()) and pa.personnel_id=hp_staff_documents.personnel_id) or exists(select 1 from public.hp_user_facilities pf where pf.user_id=(select auth.uid()) and (pf.role='ADMIN' or (pf.role='STAFF' and pf.facility_code=hp_staff_documents.facility_code))));
